demo.css:
/* Bare for visningen: meldingene legger seg i hjørnet av boksen, slik de
		   legger seg i hjørnet av vinduet i en app. Høyden gir dem plass. */
		.flate { min-block-size: 10rem; }

/* Dine egne klasser. De to reglene er alt som skal til. */
.sak-siste-linje {
  inline-size: 70%;
}

.sak-bilde {
  --lt-skeleton-height: var(--lt-spacing-12);
}

/* Bare for visningen: linja legger seg øverst i boksen, slik den legger
		   seg øverst i vinduet i en app. Plassen her gjør at den ikke dekker
		   knappene. En konsument trenger ingenting av dette. */
		.flate { padding-block-start: var(--lt-spacing-12); }

/* Boblen ligger over utløseren, og trenger litt luft i denne boksen for
       å ikke bli klippet. I en ekte side er det plassen på siden som avgjør. */
    .lt-tooltip { margin-block-start: var(--lt-spacing-8); }

